import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`inventory-forecasting`,heroTitle:`Stop guessing what to reorder.`,heroSubtitle:`Perplexity Computer reads your sales, forecasts demand, and flags what to reorder — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Forecast demand by SKU for the next 30, 60, and 90 days`,`Calculate reorder points and recommended order quantities`,`Flag SKUs at risk of stocking out or overstocking`,`A demand forecast by SKU — ready to use`],generatingSteps:[`Reviewing what you described`,`Designing an agent for your task`,`Configuring the analysis`,`Setting up your deliverable`],featureSectionTitle:`From spreadsheets to a reorder plan`,featureCardTitles:[`Connects to your ops stack`,`Outputs you can order from`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Shopify, Airtable, Notion — Computer reads your sales and builds the forecast in the tools you already use.`,`A demand forecast by SKU. Reorder points. A stockout risk list. A reorder plan.`],capabilitySectionTitle:`Your demand planner, on autopilot`,capabilitySectionSubtitle:`Share your sales data, step away, and come back to a forecast and a reorder plan.`,capabilityCards:[{title:`Demand Forecast`,description:`Computer can forecast demand by SKU for the next 30, 60, and 90 days.`},{title:`Reorder Points`,description:`Computer can calculate reorder points and recommended order quantities.`},{title:`Risk Flags`,description:`Computer can flag SKUs at risk of stocking out or overstocking.`},{title:`Connect Your Tools`,description:`Computer can pull sales from Shopify and build the plan in Sheets and Airtable.`},{title:`Remembers Your Catalog`,description:`Computer can remember your SKUs and seasonality for every forecast.`},{title:`Monitor & Alert`,description:`Computer can watch your stock and flag what to reorder this week.`}]});export{t as default};
